WITH store_stats AS (SELECT store_id, ROUND((100 * SUM(CASE WHEN channel = 'web' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_web, MAX(discount) - MIN(discount) AS discount_range FROM orders WHERE status NOT IN ('COMPLETED', 'RETURNED') GROUP BY store_id) SELECT s.id, s.sqft, s.city, ss.pct_web, ss.discount_range FROM stores s JOIN store_stats ss ON s.id = ss.store_id ORDER BY discount_range DESC, s.city, id LIMIT 5
